assert.deepEqual(twoSum([-1, -2, -3, -4, -5], -8), [2, 4]);
assert.deepEqual(twoSum([0, 4, 0], 0), [0, 2]); // index 0 is a real answer
assert.equal(twoSum([1, 2], 10), null);
assert.equal(twoSum([], 1), null);

