p-best-time-to-buy-and-sell-stock.starter:
// Return the largest profit from buying on one day and selling on a later day, or 0 if no profit is possible.
function maxProfit(prices: number[]): number {
  throw new Error('Not implemented');
}

p-best-time-to-buy-and-sell-stock.solution:
function maxProfit(prices: number[]): number {
  let lowest = Infinity;
  let best = 0;
  for (const price of prices) {
    lowest = Math.min(lowest, price);
    best = Math.max(best, price - lowest);
  }
  return best;
}

