p-product-of-array-except-self.starter:
// Return out where out[i] is the product of every element except nums[i]. O(n) and no division.
function productExceptSelf(nums: number[]): number[] {
  throw new Error('Not implemented');
}

p-product-of-array-except-self.solution:
function productExceptSelf(nums: number[]): number[] {
  const n = nums.length;
  const out = new Array<number>(n).fill(1);
  let left = 1;
  for (let i = 0; i < n; i++) {
    out[i] = left;
    left *= nums[i];
  }
  let right = 1;
  for (let i = n - 1; i >= 0; i--) {
    out[i] *= right;
    right *= nums[i];
  }
  return out.map((x) => (x === 0 ? 0 : x)); // turn -0 into 0
}

