p-longest-consecutive-sequence.starter:
// Return the length of the longest run of consecutive integers among the values of nums, in O(n).
function longestConsecutive(nums: number[]): number {
  throw new Error('Not implemented');
}

p-longest-consecutive-sequence.solution:
function longestConsecutive(nums: number[]): number {
  const values = new Set(nums);
  let best = 0;
  for (const x of values) {
    if (values.has(x - 1)) continue; // not the start of a run
    let length = 1;
    while (values.has(x + length)) length++;
    best = Math.max(best, length);
  }
  return best;
}

