p-subarray-sum-equals-k.starter:
// Return how many contiguous, non-empty subarrays sum to k. Values can be negative.
function subarraySum(nums: number[], k: number): number {
  throw new Error('Not implemented');
}

p-subarray-sum-equals-k.solution:
function subarraySum(nums: number[], k: number): number {
  const seen = new Map<number, number>([[0, 1]]);
  let sum = 0;
  let count = 0;
  for (const x of nums) {
    sum += x;
    count += seen.get(sum - k) ?? 0;
    seen.set(sum, (seen.get(sum) ?? 0) + 1);
  }
  return count;
}

