p-container-with-most-water.starter:
// Return the most water two lines can hold: their distance times the shorter height (0 with fewer than two lines).
function maxArea(heights: number[]): number {
  throw new Error('Not implemented');
}

p-container-with-most-water.solution:
function maxArea(heights: number[]): number {
  let lo = 0;
  let hi = heights.length - 1;
  let best = 0;
  while (lo < hi) {
    best = Math.max(best, (hi - lo) * Math.min(heights[lo], heights[hi]));
    if (heights[lo] < heights[hi]) lo++;
    else hi--;
  }
  return best;
}

