p-longest-substring-without-repeating-ch.starter:
// Return the length of the longest substring of s with no repeated characters.
function lengthOfLongestSubstring(s: string): number {
  throw new Error('Not implemented');
}

p-longest-substring-without-repeating-ch.solution:
function lengthOfLongestSubstring(s: string): number {
  const lastIndex = new Map<string, number>();
  let left = 0;
  let best = 0;
  for (let right = 0; right < s.length; right++) {
    const seen = lastIndex.get(s[right]);
    if (seen !== undefined) left = Math.max(left, seen + 1);
    lastIndex.set(s[right], right);
    best = Math.max(best, right - left + 1);
  }
  return best;
}

