p-minimum-window-substring.starter:
// Return the shortest substring of s that contains every character of t, counting duplicates, or '' if there is none
// (or t is empty).
function minWindow(s: string, t: string): string {
  throw new Error('Not implemented');
}

p-minimum-window-substring.solution:
function minWindow(s: string, t: string): string {
  if (t.length === 0 || t.length > s.length) return '';
  const need = new Map<string, number>();
  for (const ch of t) need.set(ch, (need.get(ch) ?? 0) + 1);

  let missing = t.length;
  let bestStart = 0;
  let bestLength = Infinity;
  let left = 0;
  for (let right = 0; right < s.length; right++) {
    const wanted = need.get(s[right]);
    if (wanted !== undefined) {
      if (wanted > 0) missing--;
      need.set(s[right], wanted - 1);
    }
    while (missing === 0) {
      if (right - left + 1 < bestLength) {
        bestLength = right - left + 1;
        bestStart = left;
      }
      const leaving = s[left++];
      const n = need.get(leaving);
      if (n !== undefined) {
        need.set(leaving, n + 1);
        if (n + 1 > 0) missing++;
      }
    }
  }
  return bestLength === Infinity ? '' : s.slice(bestStart, bestStart + bestLength);
}

