p-daily-temperatures.starter:
// For each day, return how many days until a strictly warmer temperature, or 0 if none comes.
function dailyTemperatures(temps: number[]): number[] {
  throw new Error('Not implemented');
}

p-daily-temperatures.solution:
function dailyTemperatures(temps: number[]): number[] {
  const wait = new Array<number>(temps.length).fill(0);
  const stack: number[] = []; // indices, temperatures decreasing
  for (let i = 0; i < temps.length; i++) {
    while (stack.length > 0 && temps[i] > temps[stack.at(-1)!]) {
      const day = stack.pop()!;
      wait[day] = i - day;
    }
    stack.push(i);
  }
  return wait;
}

