p-first-and-last-position-of-a-target.starter:
// Return [first, last] index of target in the sorted array, or [-1, -1] if it is absent, in O(log n).
function searchRange(nums: number[], target: number): [number, number] {
  throw new Error('Not implemented');
}

p-first-and-last-position-of-a-target.solution:
/** First index i with nums[i] >= x (nums.length if none). */
function lowerBound(nums: number[], x: number): number {
  let lo = 0;
  let hi = nums.length;
  while (lo < hi) {
    const mid = lo + ((hi - lo) >> 1);
    if (nums[mid] < x) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}
function searchRange(nums: number[], target: number): [number, number] {
  const first = lowerBound(nums, target);
  if (first === nums.length || nums[first] !== target) return [-1, -1];
  return [first, lowerBound(nums, target + 1) - 1];
}

