p-kth-largest-element.starter:
// Return the k-th largest value (k = 1 is the maximum); throw a RangeError if k is not between 1 and nums.length.
// Aim for better than sorting.
function kthLargest(nums: number[], k: number): number {
  throw new Error('Not implemented');
}

p-kth-largest-element.solution:
function kthLargest(nums: number[], k: number): number {
  if (k < 1 || k > nums.length) throw new RangeError(`k must be between 1 and ${nums.length}`);
  const a = nums.slice();
  const target = a.length - k;
  let lo = 0;
  let hi = a.length - 1;
  for (;;) {
    const pivot = a[lo + Math.floor(Math.random() * (hi - lo + 1))];
    // After the loop: a[lo..lt-1] < pivot, a[lt..gt] === pivot, a[gt+1..hi] > pivot.
    let lt = lo;
    let i = lo;
    let gt = hi;
    while (i <= gt) {
      if (a[i] < pivot) {
        [a[lt], a[i]] = [a[i], a[lt]];
        lt++;
        i++;
      } else if (a[i] > pivot) {
        [a[i], a[gt]] = [a[gt], a[i]];
        gt--;
      } else {
        i++;
      }
    }
    if (target < lt) hi = lt - 1;
    else if (target > gt) lo = gt + 1;
    else return a[target];
  }
}

