p-maximum-subarray.starter:
// Return the largest sum of a non-empty contiguous subarray; throw a RangeError for an empty array.
function maxSubArray(nums: number[]): number {
  throw new Error('Not implemented');
}

p-maximum-subarray.solution:
function maxSubArray(nums: number[]): number {
  if (nums.length === 0) throw new RangeError('nums must not be empty');
  let current = nums[0];
  let best = nums[0];
  for (let i = 1; i < nums.length; i++) {
    current = Math.max(nums[i], current + nums[i]);
    best = Math.max(best, current);
  }
  return best;
}

